  'acc.mine_empty_title': 'Tidak ada audit yang ditugaskan',
  'acc.mine_empty_sub': 'Saat akademi menamai Anda sebagai inspektur, audit akan muncul di sini.',
  'guide.accreditation.title': 'Kelola akreditasi dan audit',
  'guide.accreditation.why': 'Lacak setiap akreditasi eksternal, lisensi, dan tanda mutu yang dimiliki akademi Anda, tautkan buktinya ke catatan yang sudah Anda kelola, dan jalankan audit dengan temuan serta tindakan korektif yang tidak dapat diubah diam-diam.',
  'guide.accreditation.s1': 'Buka Akademi, lalu Akreditasi, dan ketuk Atur untuk menambah kerangka: lembaga akreditasi, jenis, tingkat, penanggung jawab, siklus perpanjangan, dan waktu pengingat.',
  'guide.accreditation.s2': 'Buka kerangka, pilih Bukti, tambahkan yang dipersyaratkan, lalu tautkan kredensial pelatih dan catatan kepatuhan. Tidak ada yang disalin, dan masa berlaku dibaca langsung.',
  'guide.accreditation.s3': 'Ketuk Jadwalkan audit, pilih jenis, tanggal, dan area yang diverifikasi, lalu secara opsional tunjuk inspektur, yang hanya dapat melihat audit tersebut.',
  'guide.accreditation.s4': 'Catat setiap temuan beserta tingkat keparahan dan tindakan korektifnya, beri setiap tindakan penanggung jawab dan tenggat, lalu tandai selesai saat pekerjaan rampung.',
  'guide.accreditation.s5': 'Ajukan ulang setelah semua temuan tinggi dan sedang diselesaikan, lalu catat keputusan inspektur. Setiap langkah disimpan dalam jejak yang terkunci.',
